/**
 * Elite Animations & Sound Utilities
 * Optimized for performance and offline reliability.
 */

export const AnimationUtils = {
    /**
     * Animates a numerical value in a DOM element.
     * @param {HTMLElement} element - Target element
     * @param {number} start - Beginning value
     * @param {number} end - Target value
     * @param {number} duration - Animation time in ms
     */
    animateValue(element, start, end, duration = 1500) {
        if (!element) return;
        let startTimestamp = null;
        const step = (timestamp) => {
            if (!startTimestamp) startTimestamp = timestamp;
            const progress = Math.min((timestamp - startTimestamp) / duration, 1);
            const value = Math.floor(progress * (end - start) + start);
            element.innerText = value.toLocaleString();
            if (progress < 1) {
                window.requestAnimationFrame(step);
            }
        };
        window.requestAnimationFrame(step);
    },

    /**
     * Plays a high-quality "Level Up" chime using Web Audio API or a pre-defined sound.
     * Using a base64 string ensures it works offline and without external loading.
     */
    playLevelUpSound() {
        try {
            // A short, premium chime sound (Base64 encoded)
            const audio = new Audio("data:audio/wav;base64,");
            audio.volume = 0.5;
            audio.play().catch(e => console.warn("Audio Context blocked until user interaction."));
        } catch (e) {
            console.warn("Sound playback failed", e);
        }
    }
};
